import { defineConfig } from "orval";

// Generates src/api/generated from the backend's Swagger spec.
// Regenerate with `yarn gen:api` (or `make gen-api` in backend/, which runs
// swag first). Never edit src/api/generated by hand.
export default defineConfig({
  yorgut: {
    input: {
      target: "../backend/docs/swagger.json",
      override: {
        transformer: "./scripts/orval-transformer.mjs",
      },
    },
    output: {
      mode: "tags-split",
      target: "src/api/generated/endpoints",
      schemas: "src/api/generated/model",
      client: "react-query",
      httpClient: "axios",
      clean: true,
      override: {
        // Every request goes through api/http.ts (auth header, 401 handling,
        // error messages). The base URL is added there too.
        mutator: {
          path: "src/api/http.ts",
          name: "apiRequest",
        },
        query: {
          // Don't hand TanStack's AbortSignal to requests: queries are not
          // cancelled when their component unmounts (same as before orval).
          signal: false,
        },
      },
    },
  },
});
